using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ValueGeneration;
using Microsoft.EntityFrameworkCore.ChangeTracking;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1 — Discriminator property renamed.
            // EF Core 9 writes "$type" instead of "Discriminator".
            // Our 500K existing docs and direct SQL queries reference
            // c.Discriminator, so pin the old name.
            entity.HasDiscriminator<string>("Discriminator")
                  .HasValue<Product>("Product");

            // BREAKING CHANGE 2 — id format changed.
            // EF Core 8 wrote id as "Product|123"; EF Core 9 writes "123".
            // Map an explicit property so existing documents stay readable.
            entity.Property<string>("CosmosId")
                  .ToJsonProperty("id")
                  .HasValueGeneratorFactory<LegacyCosmosIdGeneratorFactory>();
            entity.HasKey("CosmosId");

            // BREAKING CHANGE 3 — HasIndex is unsupported on Cosmos.
            // The old HasIndex(p => p.Sku) call now throws at model
            // validation time.  Removed — Cosmos indexing is configured
            // via the indexing policy on the container, not via EF.
        });
    }
}

class Product
{
    public int Id { get; set; }
    public string Sku { get; set; } = "";
}

/// <summary>
/// Generates Cosmos id values in the legacy "Product|{key}" format
/// that EF Core 8 produced, so existing documents remain accessible.
/// </summary>
class LegacyCosmosIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
        => $"Product|{entry.Property("Id").CurrentValue}";
}

class LegacyCosmosIdGeneratorFactory : ValueGeneratorFactory
{
    public override ValueGenerator Create(
        Microsoft.EntityFrameworkCore.Metadata.IProperty property,
        Microsoft.EntityFrameworkCore.Metadata.ITypeBase typeBase)
        => new LegacyCosmosIdGenerator();
}

